#!/usr/bin/env node
// addSpdxHeaders.mjs — put the two-line SPDX header on every source file of the package :
//
//   // SPDX-FileCopyrightText: 2026 Aaron Kaluszka
//   // SPDX-License-Identifier: Apache-2.0
//
// node scripts/addSpdxHeaders.mjs           add the header where it is missing (idempotent)
// node scripts/addSpdxHeaders.mjs --check   list files that lack it and exit 1 (test/spdxHeaderSmoke.mjs runs this)
//
// Where it goes: a shebang stays on line 1 and a GLSL `#version` stays on line 1 (it must be the first thing in a shader), so the header
// follows them. Generated files are skipped (they are rebuilt by their generators, which write their own banner), and so is any file
// that already carries another copyright or license notice: those are listed, not edited, so a maintainer can decide.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const HEADER = [
  '// SPDX-FileCopyrightText: 2026 Aaron Kaluszka',
  '// SPDX-License-Identifier: Apache-2.0',
];
const DIRS = ['src', 'scripts', 'test', 'probes'];
const EXT = new Set(['.js', '.mjs', '.cjs', '.glsl']);
const SKIP_DIR = new Set([
  'node_modules',
  'generated',
  'types',
  '.git',
  'fixtures',
  'visuals',
  'data',
]);
const SKIP_FILE = new Set(['bundled.js', 'bundledSources.js']);
const check = process.argv.includes('--check');

const missing = [],
  foreign = [];
function walk(dir) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      if (!SKIP_DIR.has(e.name)) walk(p);
      continue;
    }
    if (!EXT.has(path.extname(e.name)) || SKIP_FILE.has(e.name)) continue;
    visit(p);
  }
}
function visit(p) {
  const text = fs.readFileSync(p, 'utf8');
  const lines = text.split('\n');
  const head = lines.slice(0, 12).join('\n');
  if (/SPDX-License-Identifier/.test(head)) return;
  if (/@generated|AUTO-?GENERATED|Generated by|DO NOT EDIT/i.test(head)) return;
  if (/Copyright|Licensed under|License:/i.test(head)) {
    foreign.push(path.relative(ROOT, p));
    return;
  }
  missing.push(path.relative(ROOT, p));
  if (check) return;
  let at = 0;
  if (lines[0].startsWith('#!')) at = 1;
  if (lines[at] && /^#version\b/.test(lines[at])) at += 1;
  const insert = at === 0 ? [...HEADER, ''] : [...HEADER];
  lines.splice(at, 0, ...insert);
  fs.writeFileSync(p, lines.join('\n'));
}
for (const d of DIRS) {
  const p = path.join(ROOT, d);
  if (fs.existsSync(p)) walk(p);
}
if (foreign.length)
  console.log(
    `${foreign.length} file(s) carry another notice and were left alone:\n  ` +
      foreign.join('\n  '),
  );
if (check) {
  if (missing.length) {
    console.log(
      `${missing.length} file(s) lack the SPDX header:\n  ` +
        missing.slice(0, 40).join('\n  ') +
        (missing.length > 40 ? `\n  ... and ${missing.length - 40} more` : ''),
    );
    process.exit(1);
  }
  console.log('SPDX headers: every source file has one');
} else console.log(`added the header to ${missing.length} file(s)`);
